text:
{
  "components": [
    {
      "type": "claim",
      "quote": "Safety is of key importance to DETEC.",
      "gist": "Safety is crucial for DETEC."
    },
    {
      "type": "entity",
      "quote": "Safety Office",
      "gist": "The office responsible for safety oversight."
    },
    {
      "type": "obligation",
      "quote": "to ensure safety across a wide range of areas",
      "gist": "The Safety Office must ensure safety across many areas."
    },
    {
      "type": "claim",
      "quote": "It supports the further development of safety in land, sea and air transport, in the use, transport and distribution of energy, and for communications infrastructures.",
      "gist": "The Safety Office supports safety development in transport and energy sectors."
    },
    {
      "type": "number",
      "quote": "2003",
      "gist": "Year when DETEC created the Civil Aviation Safety Office."
    },
    {
      "type": "entity",
      "quote": "Civil Aviation Safety Office (CASO)",
      "gist": "The office created in 2003 for aviation safety."
    },
    {
      "type": "obligation",
      "quote": "to establish the highest possible safety standards in Swiss civil aviation",
      "gist": "CASO was tasked with setting the highest aviation safety standards."
    },
    {
      "type": "claim",
      "quote": "The mandate was later extended to rail transport and ship navigation.",
      "gist": "CASO's mandate was expanded to include rail and ship safety."
    },
    {
      "type": "number",
      "quote": "2021",
      "gist": "Year when CASO became the Safety Office."
    },
    {
      "type": "entity",
      "quote": "Safety Office",
      "gist": "The current name of the office formerly known as CASO."
    }
  ]
}
